def find_kth(arr1, arr2, k):
    """Return the kth smallest element (1-indexed) from two sorted arrays."""
    if not 1 <= k <= len(arr1) + len(arr2):
        raise ValueError("k must be between 1 and the total number of elements")

    i = j = 0

    while True:
        if i == len(arr1):
            return arr2[j + k - 1]
        if j == len(arr2):
            return arr1[i + k - 1]
        if k == 1:
            return min(arr1[i], arr2[j])

        half = k // 2
        next_i = min(i + half, len(arr1)) - 1
        next_j = min(j + half, len(arr2)) - 1

        if arr1[next_i] <= arr2[next_j]:
            k -= next_i - i + 1
            i = next_i + 1
        else:
            k -= next_j - j + 1
            j = next_j + 1
